cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

RWTexture2D<float4> output : register(u0);

float hash(float2 p)
{
    return frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}

float3 proceduralPattern(float2 uv, float t)
{
    float2 p = uv * 10.0;
    float cx = sin(p.x + t) * cos(p.y * 0.5 + t * 0.7);
    float cy = cos(p.x * 0.7 - t * 0.3) * sin(p.y + t * 1.1);
    float v = sin(cx * 3.14159) * cos(cy * 3.14159);
    float3 col;
    col.r = saturate(0.5 + 0.5 * sin(v * 6.0));
    col.g = saturate(0.5 + 0.5 * sin(v * 6.0 + 2.094));
    col.b = saturate(0.5 + 0.5 * sin(v * 6.0 + 4.189));
    return col;
}

[numthreads(8, 8, 1)]
void CSMain(uint3 dtid : SV_DispatchThreadID)
{
    uint2 dim;
    output.GetDimensions(dim.x, dim.y);
    if (dtid.x >= dim.x || dtid.y >= dim.y)
        return;

    float2 uv = float2(dtid.xy) / float2(dim);
    float t = time_sim_ms * 0.001;

    float blurRadius = (mouse_x / resolution_x) * 8.0 + 1.0;
    int radius = int(blurRadius);
    if (radius < 1) radius = 1;
    if (radius > 12) radius = 12;

    float3 sum = float3(0, 0, 0);
    float weightSum = 0.0;
    float sigma = float(radius) * 0.5;

    for (int dy = -radius; dy <= radius; dy++) {
        for (int dx = -radius; dx <= radius; dx++) {
            float2 sampleUV = (float2(dtid.xy) + float2(dx, dy)) / float2(dim);
            float w = exp(-(dx*dx + dy*dy) / (2.0 * sigma * sigma));
            sum += proceduralPattern(sampleUV, t) * w;
            weightSum += w;
        }
    }

    float3 color = sum / weightSum;
    output[dtid.xy] = float4(color, 1.0);
}
